#######################General purpose functions#######################
def getTracking(varelemplus,param2madx,cellfile,madxfile):
	lines=[]
	nlines=[]
	madxlines=[]
	tracking=[]
	with open(cellfile,'r') as file:
		for line in file:
        		lines.append(line.strip())
	for line in lines:
		for k in range(len(varelemplus)):
			a=re.search(varelemplus[k]+'=',line)
			try:
				b=a[0]
			except (TypeError):
				flag=1
			else:
				nlines.append(re.sub(r'\=\S+','='+str(param2madx[k])+';',line))
				flag=0
				break
		if flag==1:
			nlines.append(line)
	instructions = [] #madx.Instructions()
	for line in nlines:
		instructions.append(line.strip())
	with open(cellfile,'w') as file0:
		for line in instructions:
			file0.write(f"{line}\n")
#	with open(cellfile,'r') as file0:
#		for line in file0:
#			print(line)
	results= subprocess.run(['./madx', cellfile], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL) #instructions.execute()
	with open(madxfile,'r') as file:
		for line in file:
			madxlines.append(line.strip())
	for line in madxlines:
		if line[0]!='#':
			if line[0]=='1':
				tracking.append(line.split()[1:6])
	tracking=map(lambda line: list(map(lambda s: float(s),line)),tracking)
	tracking=list(tracking)
#	tracking=pd.DataFrame(tracking,columns=['turn','x','px','y','py'])
	return tracking

