def on_generation_callback(ga_instance):
	best_fitness = ga_instance.best_solution(pop_fitness=ga_instance.last_generation_fitness)[1]
	print(f"Generation {ga_instance.generations_completed}: Best Fitness = {best_fitness}")

def fitness_func(ga_instance, solution, solution_idx):
	target_value = 0.0
	ofun=objfunc(solution)
	fitness = -np.abs(ofun) # Negative for maximization
	return fitness

